local sourceCache,routeCache={},{}
function M:TextureSourcePath(path)
    if type(path)~="string"then return path end
    if sourceCache[path] then return sourceCache[path] end
    local input=path
    path=self:ResolveAssetPath(path)
    local normalized=path:gsub("/","\\"):gsub("\\+","\\")
    if normalized:sub(1,#ROOT):lower()~=ROOT:lower()then sourceCache[input]=path;return path end
    local rel=normalized:sub(#ROOT+1):lower()
    local resolved=ROOT..(originals[rel]or canonical[rel]or normalized:sub(#ROOT+1))
    sourceCache[input]=resolved
    return resolved
end
function M:SameTexture(a,b)
    a,b=self:TextureSourcePath(a),self:TextureSourcePath(b)
    if type(a)=="string"and type(b)=="string"then return a:lower()==b:lower()end
    return a==b
end
function M:TexturePath(owner,path,role)
    if type(path)~="string"then return path end
    local id=type(owner)=="table"and owner.id or owner
    local key=tostring(id)..":"..(role or "file")
    local cache=routeCache[key]
    if cache and cache[path] then return cache[path] end
    local source=self:TextureSourcePath(path)
    local paths=routes[key]
    local dest=paths and paths[source:sub(#ROOT+1):lower()]
    local resolved=dest and ROOT..dest or self:ResolveAssetPath(path)
    if not cache then cache={};routeCache[key]=cache end
    cache[path]=resolved
    return resolved
end
local normalizedFields=setmetatable({},{__mode="k"})
local textureFields={"file","materialPath","partyOriginalFile","partyMaterialPath"}
function M:NormalizeNodeTextures(design)
    for _,n in ipairs(design.nodes or {})do
        -- Saved paths can change in place (including imports and conditions).
        -- Compare the actual values; retain only a session-local weak snapshot.
        local previous=normalizedFields[n]
        if not previous or previous.owner~=n.id or previous.file~=n.file
            or previous.materialPath~=n.materialPath or previous.partyOriginalFile~=n.partyOriginalFile
            or previous.partyMaterialPath~=n.partyMaterialPath then
            previous=previous or {};previous.owner=n.id
            for _,field in ipairs(textureFields)do
                if n[field]then n[field]=self:TexturePath(n,n[field],field=="partyOriginalFile"and "file"or field)end
                previous[field]=n[field]
            end
            normalizedFields[n]=previous
        end
        for _,condition in ipairs(n.conditions or {})do for _,change in ipairs(condition.changes or {})do
            if change.field=="file"or change.field=="materialPath"then
                local last=normalizedFields[change]
                if not last or last.owner~=n.id or last.role~=change.field or last.value~=change.value then
                    change.value=self:TexturePath(n,change.value,change.field)
                    normalizedFields[change]={owner=n.id,role=change.field,value=change.value}
                end
            end
        end end
    end
end

